('atlas.cancel_flower_demand_order_for_member_v1(uuid, uuid, text, text, text)','app_endpoint','verified','active',true,true,true,1,0,jsonb_build_object('purpose','Append a cancellation fact for independent flower demand','boundary','active farm membership; Farm Hand may cancel only demand they recorded','historyTruth','original demand and lines remain immutable','inventoryTruth','cancellation does not reverse or create any Ready inventory claim'),now()),
('atlas.owner_operator_cancel_flower_demand_order_v1(uuid, uuid, text, text, text)','owner_admin_endpoint','verified','active',true,true,true,1,0,jsonb_build_object('purpose','Append the same independent-demand cancellation while Owner operates as an effective farm membership','boundary','owner_operator_context_v1 resolves effective membership and farm scope','historyTruth','original demand stays immutable'),now()),
