('atlas.owner_operator_record_flower_standing_order_v1(uuid, uuid, text, text, text, time without time zone, date, date, integer, jsonb, text, text)','owner_admin_endpoint','verified','active',true,true,true,1,0,jsonb_build_object('purpose','Record a recurring flower-demand definition in Owner operator mode','boundary','effective role must still have Owner or Manager commercial authority','inventoryTruth','operator mode cannot manufacture supply or sale truth','clockTruth','no Worker Day or Principal work is created by definition alone'),now()),
